def mapWordWeights(words, weights):
    result = []

    for word in words:
        # Weight of the word is the sum of the weights of its letters
        total = 0
        for ch in word:
            total += weights[ord(ch) - ord('a')]
        # Reverse alphabetical mapping: 0 -> 'z', 1 -> 'y', ..., 25 -> 'a'
        result.append(chr(ord('z') - total % 26))

    # Concatenate the mapped letters in order
    return "".join(result)
